    const notes = [];
    if (failed.length) notes.push(`<details class="fold"><summary>${plural(failed.length, 'file')} couldn’t be read (videos or other non-image files)</summary><div class="receipt-body">${failed.map((e) => `<div id="ev-${Number(e.id)}">${esc((e.detail || {}).error || e.summary || '')}</div>`).join('')}</div></details>`);
    if (unread) notes.push(`<p class="muted small" style="margin-top:12px">${plural(unread, 'image')} in these posts ${unread === 1 ? 'hasn’t' : 'haven’t'} been read by the model yet.</p>`);
    return `<section class="card o-media" aria-labelledby="h-media"><div class="card-head"><h2 id="h-media">Images</h2><span class="label">Nemotron Super VL</span></div>
      ${items.join('')}${notes.join('')}</section>`;
  }
